import { isObject } from '../utils.js';
export const ownCopy = (value, nestedRecords) => {
    const copy = Object.assign({}, value);
    for (const key of nestedRecords) {
        const nested = Reflect.get(copy, key);
        if (isObject(nested)) {
            Reflect.set(copy, key, Object.assign({}, nested));
        }
    }
    return copy;
};
